import React, { useEffect, useRef, useState } from 'react';
import { createRoot } from 'react-dom/client';
import { ArrowDown, ArrowDownLeft, ArrowDownToLine, ArrowRight, ArrowUpRight, BarChart3, Check, CheckCheck, ChevronDown, ChevronLeft, ChevronRight, CircleDollarSign, Coins, Database, Ellipsis, ExternalLink, Eye, EyeOff, FileClock, FileSpreadsheet, FolderOpen, Globe2, HelpCircle, Info, LayoutDashboard, Leaf, Loader2, LockKeyhole, Menu, MoreHorizontal, Plus, RefreshCw, Search, Settings2, ShieldCheck, SlidersHorizontal, Sparkles, TrendingUp, Undo2, Upload, Wallet, X, Pencil, Trash2, AlertTriangle, ArrowUpDown, type LucideIcon } from 'lucide-react';
import { api, day, downloadCSV, localDate, money, num, pct, timestamp } from './api';
